R=Path(__file__).resolve().parent;V=Path('/workspace/codex/results/GSE151530_only_TCGA_PGAM5_deconvolution');src=pd.read_csv(V/'TCGA_LIHC_PGAM5_macrophage_estimates.csv').set_index('patient');p=pd.read_csv(R/'patient_scores.csv').set_index('patient');joined=pd.read_csv(R/'patient_scores_survival_join.csv');stats=pd.read_csv(R/'survival_statistics.csv');curves=pd.read_csv(R/'KM_curve_values.csv');risks=pd.read_csv(R/'KM_numbers_at_risk.csv');assert p.index.equals(src.index);assert np.array_equal(p.group,src.group);assert np.array_equal(p.exploratory_target_fraction,src.exploratory_target_fraction);assert p.group.value_counts().to_dict()=={'Low':256,'High':115};assert joined.patient.is_unique and len(joined)==371;checks=[]
