 checks.append({'endpoint':ep,'eligible_patients':len(t),'high':int(z.high_patients),'low':int(z.low_patients),'excluded':int(z.excluded_patients),'independent_chi_square':stat,'independent_p':pv,'source_groups_unchanged':True,'all_risk_counts_match':True,'exported_KM_curve_recomputed':True})
